import os,sys,re
REV=int(sys.argv[1]); ENV=sys.argv[2]; HOST=sys.argv[3]
hist='/app/config-history'
def cfgfile(rel):
    for r in range(REV+1,10000):
        d=f'{hist}/r{r:04d}'
        if not os.path.isdir(d):
            if r>1000: break
            continue
        p=f'{d}/prev/{rel}'
        if os.path.exists(p): return p
    return f'/app/config/{rel}'
def path_of(abspath):
    if abspath.startswith('/app/config/'): return cfgfile(abspath[len('/app/config/'):])
    return abspath
def read(logical,svc,vals,trace):
    real=path_of(logical)
    sec=None
    for line in open(real):
        line=line.strip()
        if not line or line.startswith('#'): continue
        m=re.match(r'\[(.*)\]',line)
        if m: sec=m.group(1); continue
        k,v=[x.strip() for x in line.split('=',1)]
        if k=='include':
            if sec is not None: continue
            p=v.replace('${env}',ENV).replace('${host}',HOST)
            read(os.path.normpath(os.path.join(os.path.dirname(logical),p)),svc,vals,trace); continue
        if sec is None or sec==svc:
            vals[k]=v; trace.append((k,v,logical,sec))
for svc in sorted(os.listdir('/app/services')):
    vals={};trace=[]
    read(f'/app/services/{svc}/service.conf',svc,vals,trace)
    pb=vals.get('port_base');po=vals.get('port_offset');
    main=int(pb)+int(po) if pb and po else None
    print(svc,'enabled=',vals.get('enabled'),'main=',main,'admin=',vals.get('admin_port'))
    if len(sys.argv)>4 and svc==sys.argv[4]:
        for t in trace:
            if t[0] in('admin_port','port_base','port_offset','enabled'):print('   ',t)
EOF
